<?php require 'config/db.php'; if(empty($_SESSION['cart'])){header('Location:menu.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo->beginTransaction();$total=0;foreach($_SESSION['cart'] as $i){$s=$pdo->prepare('SELECT stock,price FROM drinks WHERE id=? FOR UPDATE');$s->execute([$i['id']]);$d=$s->fetch();if(!$d||$d['stock']<$i['qty'])throw new Exception($i['name'].' does not have enough stock.');$total+=$d['price']*$i['qty'];}
$s=$pdo->prepare('INSERT INTO orders(user_id,customer_name,phone,address,fulfillment,total) VALUES(?,?,?,?,?,?)');$s->execute([$_SESSION['user']['id']??null,$_POST['name'],$_POST['phone'],$_POST['address'],$_POST['fulfillment'],$total]);$oid=$pdo->lastInsertId();foreach($_SESSION['cart'] as $i){$s=$pdo->prepare('INSERT INTO order_items(order_id,drink_id,drink_name,price,qty,size,sugar,ice) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$oid,$i['id'],$i['name'],$i['price'],$i['qty'],$i['size'],$i['sugar'],$i['ice']]);$pdo->prepare('UPDATE drinks SET stock=stock-? WHERE id=?')->execute([$i['qty'],$i['id']]);}$pdo->prepare('INSERT INTO payments(order_id,method,status,amount) VALUES(?,?,?,?)')->execute([$oid,$_POST['payment'],'Paid',$total]);$pdo->commit();$_SESSION['cart']=[];header('Location:order.php?id='.$oid);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | DrinkShop</title><link rel="stylesheet" href="css/style.css"></head><body><header><nav><a class="logo" href="index.php">🥤 DrinkShop</a><div><a href="menu.php">Menu</a><a href="cart.php">Cart</a></div></nav></header><main><div class="checkout-grid"><div class="form-card"><div class="form-head"><h1>Checkout</h1><p class="form-subtitle">Complete your details and choose how you want to receive your drink.</p></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><div class="field"><label>Customer name</label><input name="name" placeholder="Full name" required></div><div class="field"><label>Phone number</label><input name="phone" placeholder="e.g. 012 345 678" required></div><div class="field"><label>Delivery address</label><textarea name="address" placeholder="House number, street, area..."></textarea></div><div class="choice-grid"><div class="field"><label>Receive order</label><select name="fulfillment"><option value="delivery">Delivery</option><option value="pickup">Pickup</option></select></div><div class="field"><label>Payment method</label><select name="payment"><option>Cash</option><option>ABA / QR</option></select></div></div><button class="btn">Confirm order →</button></form></div><aside class="summary-card"><div class="summary-icon">🧋</div><h2>Almost there!</h2><p class="muted">Please double-check your contact information before confirming.</p><ul><li>Stock is checked before your order is created.</li><li>Your drink preferences stay with each item.</li><li>You can follow the order status after checkout.</li></ul><a href="cart.php">← Review cart</a></aside></div></main></body></html>